        if node[0] == 'IN':
            continue
        elif node[0] == 'NOT':
            child = node[1]
            adj[child].append(i)
            in_degree[i] += 1
        else:
            child1, child2 = node[1], node[2]
            adj[child1].append(i)
            adj[child2].append(i)
            in_degree[i] += 2

    # Compute original output
    original_values = [0] * (n+1)
    q = deque()
    for i in range(1, n+1):
        if in_degree[i] == 0:
            q.append(i)
            if graph[i-1][0] == 'IN':
                original_values[i] = graph[i-1][1]

    while q:
        u = q.popleft()
        node_type = graph[u-1][0]
        if node_type == 'IN':
            continue
        elif node_type == 'NOT':
            v = graph[u-1][1]
            original_values[u] = 1 - original_values[v]
