            if node_type == 'AND':
                original_values[u] = original_values[v1] & original_values[v2]
            elif node_type == 'OR':
                original_values[u] = original_values[v1] | original_values[v2]
            elif node_type == 'XOR':
                original_values[u] = original_values[v1] ^ original_values[v2]
            for neighbor in adj[u]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    q.append(neighbor)

    original_output = original_values[1]

