            elif node_type == 'NOT':
                v = graph[u-1][1]
                new_values[u] = 1 - new_values[v]
            else:
                v1, v2 = graph[u-1][1], graph[u-1][2]
                if node_type == 'AND':
                    new_values[u] = new_values[v1] & new_values[v2]
                elif node_type == 'OR':
                    new_values[u] = new_values[v1] | new_values[v2]
                elif node_type == 'XOR':
                    new_values[u] = new_values[v1] ^ new_values[v2]

